CREATE DATABASE hr_enterprise;
CREATE TABLE IF NOT EXISTS employees (id BIGSERIAL PRIMARY KEY, emp_code TEXT UNIQUE NOT NULL, name TEXT NOT NULL, national_id TEXT, phone TEXT, email TEXT, job TEXT, department TEXT, unit TEXT, status TEXT DEFAULT 'على رأس العمل', basic_salary NUMERIC DEFAULT 0, allowances NUMERIC DEFAULT 0, total_salary NUMERIC DEFAULT 0, updated_at TIMESTAMPTZ DEFAULT now());
CREATE INDEX IF NOT EXISTS idx_employees_department ON employees(department);
CREATE TABLE IF NOT EXISTS employee_evaluations (id BIGSERIAL PRIMARY KEY, emp_code TEXT NOT NULL, period TEXT NOT NULL, score NUMERIC DEFAULT 0, goals_score NUMERIC DEFAULT 0, attendance_score NUMERIC DEFAULT 0, discipline_score NUMERIC DEFAULT 0, notes TEXT, created_by TEXT, created_at TIMESTAMPTZ DEFAULT now(), UNIQUE(emp_code,period));
CREATE TABLE IF NOT EXISTS payroll (id BIGSERIAL PRIMARY KEY, emp_code TEXT NOT NULL, period TEXT NOT NULL, basic NUMERIC DEFAULT 0, allowances NUMERIC DEFAULT 0, deductions NUMERIC DEFAULT 0, overtime NUMERIC DEFAULT 0, bonuses NUMERIC DEFAULT 0, net NUMERIC DEFAULT 0, status TEXT DEFAULT 'مسودة', locked_at TIMESTAMPTZ, locked_by TEXT, UNIQUE(emp_code,period));
CREATE TABLE IF NOT EXISTS audit (id BIGSERIAL PRIMARY KEY, ts TIMESTAMPTZ DEFAULT now(), username TEXT, role TEXT, action TEXT, entity TEXT, record_key TEXT, details TEXT);
CREATE TABLE IF NOT EXISTS notifications (id BIGSERIAL PRIMARY KEY, user_name TEXT, title TEXT, message TEXT, created_at TIMESTAMPTZ DEFAULT now(), read_at TIMESTAMPTZ);
CREATE TABLE IF NOT EXISTS employee_requests (id BIGSERIAL PRIMARY KEY, emp_code TEXT NOT NULL, request_type TEXT NOT NULL, payload_json JSONB DEFAULT '{}'::jsonb, status TEXT DEFAULT 'pending', manager_user TEXT, hr_user TEXT, created_at TIMESTAMPTZ DEFAULT now(), updated_at TIMESTAMPTZ DEFAULT now());
CREATE TABLE IF NOT EXISTS alert_rules (id BIGSERIAL PRIMARY KEY, key TEXT UNIQUE, title TEXT, severity TEXT DEFAULT 'warn', enabled BOOLEAN DEFAULT true, threshold NUMERIC DEFAULT 30, unit TEXT DEFAULT 'days', audience TEXT DEFAULT 'HR', created_at TIMESTAMPTZ DEFAULT now(), updated_at TIMESTAMPTZ DEFAULT now());
CREATE TABLE IF NOT EXISTS alert_events (id BIGSERIAL PRIMARY KEY, alert_key TEXT UNIQUE, severity TEXT, title TEXT, message TEXT, emp_code TEXT, created_at TIMESTAMPTZ DEFAULT now(), resolved_at TIMESTAMPTZ);
CREATE TABLE IF NOT EXISTS evaluation_stats (id BIGSERIAL PRIMARY KEY, emp_code TEXT, period TEXT, department_avg NUMERIC, unit_avg NUMERIC, job_avg NUMERIC, manager_avg NUMERIC, percentile NUMERIC, z_score NUMERIC, anomaly_level TEXT, explanation TEXT, created_at TIMESTAMPTZ DEFAULT now(), UNIQUE(emp_code,period));
